      pulled.eventId + ' != ' + eventId
    );
  }

  const rows =
    pulled.rows || [];

  if (!rows.length) {
    throw new Error(
      'Opening KG rows empty.'
    );
  }

  const openingSequence =
    Date.now() * 10 + 5;

  const saved =
    await saveOddsKgBatch({
      eventId,
      rows,
      captureType: 'opening',
      sourceName:
        pulled.sourceName,
